using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using Mori;
namespace MoriDesk {
 public static class BoardTests {
  const BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
  static IEnumerable<T> Children<T>(DependencyObject root)where T:DependencyObject{for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);if(child is T)yield return (T)child;foreach(var next in Children<T>(child))yield return next;}}
  public static void Run(string root,Action<bool,string> check){
   string originals=Path.Combine(root,"board-originals");Directory.CreateDirectory(originals);string photo=Path.Combine(originals,"林间参考.png");File.Copy(Path.Combine(root,"reference-photo.png"),photo);string folder=Path.Combine(originals,"机器人项目");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"不会导入.mp4"),"fixture only");string model=Path.Combine(originals,"结构方案.STEP");File.WriteAllText(model,"fixture");byte[] before=File.ReadAllBytes(photo);
   using(var lib=new Library(Path.Combine(root,"board-library"))){
    var legacy=new ReferenceStore(lib.Db);string old=legacy.AddFolder("旧快捷收藏");legacy.Add(new[]{model},old);var board=new BoardStore(lib);check(board.Categories().Any(c=>c.Id==old),"legacy reference categories mapped without copying originals");
    string inspiration=board.CreateBox("图片参考"),project=board.CreateBox("项目资料");var managed=lib.Import(photo,inspiration,"网上收藏示例","https://example.org/sample","图像","fixture").Item;lib.ImportBookmark("https://example.org/","网址单独显示","");
    check(board.AddShortcuts(new[]{photo,folder},"")==2,"external files and folders become exactly two shortcuts");check(lib.All().Count==2,"folder shortcut never expands/imports contained video");check(board.All().Count==5,"managed and reference rows share one index projection");
    var all=board.All();var local=all.Single(i=>i.Path==photo);var download=all.Single(i=>i.Asset!=null&&!i.Asset.IsBookmark);check(local.Shortcut&&!download.Shortcut,"storage mode remains explicit");check(download.Path==lib.FullPath(managed)&&File.Exists(download.Path)&&download.Source=="https://example.org/sample","downloaded asset has a real local path and source URL");check(BoardStore.InSection(local,"all")&&BoardStore.InSection(download,"all")&&BoardStore.InSection(all.Single(i=>i.Path==model),"all"),"all materials includes images, model shortcuts and copies");check(!BoardStore.InSection(all.Single(i=>i.Section=="websites"),"all"),"websites remain separate");
    board.Move(new[]{local.Id,download.Id},project);all=board.All();check(all.Single(i=>i.Id==local.Id).Groups.Single()==project&&all.Single(i=>i.Id==download.Id).Groups.Single()==project,"mixed selection moves to one category");check(board.Undo()&&board.All().Single(i=>i.Id==local.Id).Groups.Length==0&&board.All().Single(i=>i.Id==download.Id).Groups.Single()==inspiration,"mixed classification undone atomically");
    board.Move(new[]{local.Id,download.Id},project);board.DeleteBox(project);check(board.All().Where(i=>i.Id==local.Id||i.Id==download.Id).All(i=>i.Groups.Length==0),"deleting a box unfiles both storage types");check(board.Undo()&&board.Boxes(board.All()).Single(b=>b.Id==project).Count==2,"undo restores box and all memberships");
    board.Remove(new[]{local.Id,download.Id});check(!board.All().Any(i=>i.Id==local.Id||i.Id==download.Id)&&File.Exists(photo)&&File.Exists(download.Path),"mixed remove never physically deletes source or library copy");check(lib.All().Single(a=>a.Id==managed.Id).Deleted,"managed deletion goes to recycle bin");check(board.Undo()&&board.All().Any(i=>i.Id==local.Id)&&!lib.All().Single(a=>a.Id==managed.Id).Deleted,"undo restores both references and copies");
    board.DeleteBox(old);check(!new BoardStore(lib).Categories().Any(c=>c.Id==old),"deleted legacy category does not reappear on restart");check(board.Undo(),"undo old category deletion");
    int count=board.All().Count;bool failed=false;try{board.AddShortcuts(new[]{photo,Path.Combine(root,"not-found")},"");}catch{failed=true;}check(failed&&board.All().Count==count,"invalid drop is atomic");check(board.AddShortcuts(new[]{photo.ToUpperInvariant()},"")==0,"same local path is not duplicated");
    string renamed=Path.Combine(originals,"参考新位置.png");File.Move(photo,renamed);board.Relink(local,renamed);check(board.All().Single(i=>i.Id==local.Id).Path==renamed,"missing local shortcut can be relinked");File.Move(renamed,photo);board.Relink(board.All().Single(i=>i.Id==local.Id),photo);
    var sourceThumb=BoardImage.Read(board.All().Single(i=>i.Id==local.Id),lib);check(sourceThumb!=null&&sourceThumb.PixelWidth<=256&&sourceThumb.IsFrozen,"local thumbnail stays small and thread-safe");check(BoardImage.Read(board.All().Single(i=>i.Directory),lib)==null,"folder preview never enumerates children");check(BoardImage.Read(board.All().Single(i=>i.Path==model),lib)==null,"CAD file not parsed for thumbnail");
    // Keep a realistic detached layout fixture, never read the user's library.
    board.Move(new[]{local.Id},"");board.AddShortcuts(new[]{Path.Combine(root,"reference-photo.png")},inspiration);
    Entry.BoardEnabled=true;var main=new MainWindow(lib){PreviewMode=true};try{
     var page=(BoardPage)typeof(MainWindow).GetField("boardPage",Flags).GetValue(main);check(page!=null&&page.IsEnabled,"unified board is the main startup view");check(((Button)main.Window.FindName("Import")).Visibility==Visibility.Collapsed,"old ambiguous importer hidden on desktop view");
     main.SetSection("pictures");check(page.Section=="pictures","picture navigation uses unified data");main.SetSection("bookmarks");check(page.Visibility==Visibility.Collapsed,"website page remains independent");main.SetSection("assets");check(page.Visibility==Visibility.Visible&&page.Section=="all","return to all restores unified board");
     var shortcutNav=(Button)typeof(MainWindow).GetField("referenceNav",Flags).GetValue(main);main.SetSection("shortcuts");check(shortcutNav.Background==main.Window.FindResource("AccentSoft"),"shortcut navigation is highlighted only while active");main.SetSection("bookmarks");check(shortcutNav.Background==main.Window.FindResource("Panel"),"leaving shortcuts clears stale navigation highlight");main.SetSection("pictures");page.ShowSection("documents");page.SectionChanged();check(((Button)main.Window.FindName("Documents")).Background==main.Window.FindResource("AccentSoft")&&((Button)main.Window.FindName("Pictures")).Background==main.Window.FindResource("Panel"),"accepted import section change synchronizes sidebar");main.SetSection("assets");
     page.tiles.SelectedItem=page.tiles.Items.OfType<BoardItem>().Single(i=>i.Id==local.Id);check(((TextBox)page.content.FindName("LocalPath")).Text==photo,"inspector shows full shortcut address");
     var body=(FrameworkElement)main.Window.Content;main.Window.Content=null;body.Resources.MergedDictionaries.Add(main.Window.Resources);body.Width=1380;body.Height=860;body.Measure(new Size(1380,860));body.Arrange(new Rect(0,0,1380,860));body.UpdateLayout();
     var box=page.tiles.Items.OfType<BoardBox>().Single(b=>b.Id==inspiration);var target=(ListViewItem)page.tiles.ItemContainerGenerator.ContainerFromItem(box);check(target!=null,"category box is a realised drop target");
     var data=new DataObject(BoardPage.DragFormat,new[]{local.Id});var args=(DragEventArgs)Activator.CreateInstance(typeof(DragEventArgs),Flags,null,new object[]{data,DragDropKeyStates.None,DragDropEffects.Move,target,new Point(10,10)},System.Globalization.CultureInfo.InvariantCulture);args.RoutedEvent=UIElement.PreviewDropEvent;target.RaiseEvent(args);check(args.Handled&&board.All().Single(i=>i.Id==local.Id).Groups.Single()==inspiration,"actual WPF routed drag moves shortcut into a box");
     page.ShowSection("pictures");((TextBox)page.content.FindName("Search")).Text="网上收藏";typeof(BoardPage).GetMethod("Render",Flags,null,Type.EmptyTypes,null).Invoke(page,null);page.tiles.SelectedItem=page.tiles.Items.OfType<BoardItem>().Single();check(((TextBox)page.content.FindName("LocalPath")).Text==download.Path&&((TextBox)page.content.FindName("Source")).Text==download.Source,"managed inspector includes both local path and web source");
     page.ShowSection("all");body.UpdateLayout();foreach(string theme in new[]{"light","dark"}){Theme.Set(theme);body.UpdateLayout();foreach(var img in Children<BoardImage>(body))try{img.Source=BoardImage.Read(img.DataContext as BoardItem,lib);}catch{}var render=new RenderTargetBitmap(1380,860,96,96,PixelFormats.Pbgra32);render.Render(body);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(render));using(var s=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"board-ui-"+theme+".png")))encoder.Save(s);}
     check(MainWindow.ShortcutDropEffect(DragDropEffects.Move)==DragDropEffects.None,"never tell Explorer to move/delete an original");check(MainWindow.ShortcutDropEffect(DragDropEffects.Copy)==DragDropEffects.Copy,"sources without Link effect still supported without moving originals");
    }finally{main.Window.Close();Entry.BoardEnabled=false;}
    board.DeleteBoxes(new[]{inspiration,project});check(!board.Categories().Any(c=>c.Id==inspiration||c.Id==project)&&board.All().Any(i=>i.Id==local.Id),"batch box removal preserves materials");check(board.Undo()&&board.Categories().Any(c=>c.Id==inspiration)&&board.Categories().Any(c=>c.Id==project),"batch box removal has one-step undo");
    var alias=board.All().Single(i=>i.Id==local.Id);board.UpdateInformation(alias,"参考图片别名","","");check(board.All().Single(i=>i.Id==local.Id).Name=="参考图片别名"&&File.Exists(photo),"editing shortcut name does not rename source");check(board.Undo()&&board.All().Single(i=>i.Id==local.Id).Name==alias.Name,"shortcut alias undo");
    check(File.ReadAllBytes(photo).SequenceEqual(before)&&File.Exists(Path.Combine(folder,"不会导入.mp4")),"test actions preserve originals and folder contents");
    var current=board.All().Single(i=>i.Id==local.Id);board.CopyToLibrary(current);check(!board.All().Any(i=>i.Id==local.Id)&&File.Exists(photo),"save independent copy replaces shortcut only after import succeeds");
   }
  }
 }
}
